import {Test} from "forge-std/Test.sol";
import {C, LogFile} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    LogFile log;

    function setUp() public {
        c = new C();
        log = new LogFile();
    }

    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        amount = bound(amount, 1 wei, 10 ether);

        // configure the log before initialization
        vm.prank(actor);
        c.SetLogFile(address(log));
        c.Initialized();

        // a deposit must be recorded in the configured log
        vm.deal(actor, amount);
        vm.prank(actor);
        c.Deposit{value: amount}();

